from mk import *

def fig():
    g = Fig(560, 300, "גרף מהירות-זמן של אחד הכדורים: קו ישר מ-5- מטר לשנייה ב-0 שניות עד 45 מטר לשנייה ב-5 שניות. הכיוון החיובי כלפי מטה")
    X, Y = g.graph(80, 250, 400, 210, "t (s)", "v (m/s)", xticks=[(t, str(t)) for t in range(1, 6)], yticks=[(v, str(v)) for v in (-10, 10, 20, 30, 40, 50)], xmax=5.5, ymin=-10, ymax=50)
    g.plot(X, Y, [(0, -5), (5, 45)])
    for t in range(6):
        g.dot(X(t), Y(-5 + 10 * t), 3)
    return g

E(id="bagrut-2018-q1", year=2018, label="2018 שאלה 1", topic="kinematics", sub="kin-free-fall", diff=3, fig=fig,
  stem=r"בעבודת חקר של תלמידי מגמת פיזיקה בבית ספר תיכון, החליטו התלמידים לבחון את מאפייני התנועה של גופים שנזרקים אנכית. לשם כך הם עלו על מגדל שגובהו $H$, וזרקו באותו רגע שלושה כדורים זהים: $A$, $B$ ו-$C$. כדור $A$ נזרק כלפי מטה במהירות התחלתית שגודלה $v_0$, כדור $B$ נזרק כלפי מעלה במהירות התחלתית שגודלה זהה לגודל המהירות ההתחלתית של כדור $A$, וכדור $C$ שוחרר ממנוחה. שלושת הכדורים לא התנגשו במהלך תנועתם. התלמידים קבעו את כיוון הציר האנכי החיובי כלפי מטה. הם סרטטו גרף מהירות-זמן של אחד הכדורים, מרגע זריקתו עד סוף פגיעתו בקרקע. בסעיפים א-ד הנח כי אפשר להזניח את כוח החיכוך בין הכדורים לאוויר.",
  parts=[
    P("א", r"קבע אם הגרף מתאר את מהירותו של כדור $A$, של כדור $B$ או של כדור $C$. נמק את קביעתך.", choice(["A", "B", "C"], 1), ["graph", "signs"], [
        S(r"המהירות ההתחלתית בגרף", r"הכיוון החיובי כלפי מטה, ולכן מהירות שלילית פירושה כלפי מעלה", r"v(0) = -5\,\text{m/s} < 0"),
        S(r"איזה כדור נזרק כלפי מעלה", r"רק כדור $B$", r"B"),
    ], r"כדור $B$: מהירותו ההתחלתית שלילית, כלומר כלפי מעלה", key=r"B"),
    P("ב", r"חשב את גובה המגדל, $H$.", num(100, "m"), ["graph", "algebra", "signs"], [
        S(r"השטח מתחת לגרף", r"ההעתק של $B$ מהזריקה עד הקרקע. השטח השלילי (עלייה) מוחסר", r"\Delta y = -\tfrac{1}{2} \cdot 0.5 \cdot 5 + \tfrac{1}{2} \cdot 4.5 \cdot 45 = -1.25 + 101.25"),
        S(r"גובה המגדל", r"ההעתק הכולל מגג המגדל עד הקרקע", r"H = 100\,\text{m}"),
        C(r"בדיקה במשוואת מקום", r"$v_0 = -5$, $a = 10$, $t = 5$", r"-5 \cdot 5 + 5 \cdot 25 = 100 \;\checkmark"),
    ], r"$100\,\text{m}$", key=r"H=100 m"),
    P("ג", r"חשב את המרחק האנכי בין מיקומו של כדור $A$ לבין מיקומו של כדור $B$, בזמן $t = 2\,\text{s}$.", num(20, "m"), ["principle", "algebra"], [
        S(r"מקום $A$", r"מהירות התחלתית $+5$ (מטה)", r"y_A = 5 \cdot 2 + 5 \cdot 4 = 30\,\text{m}"),
        S(r"מקום $B$", r"מהירות התחלתית $-5$", r"y_B = -5 \cdot 2 + 5 \cdot 4 = 10\,\text{m}"),
        S(r"המרחק", r"התאוצות שוות ומתבטלות, ונשאר הפרש המהירויות כפול הזמן", r"y_A - y_B = 20\,\text{m} = (5 - (-5)) \cdot 2"),
    ], r"$20\,\text{m}$", key=r"20 m"),
    P("ד", r"התלמידים הוסיפו לאותה מערכת צירים את הגרפים של שני הכדורים האחרים. הסבר מהי המשמעות הפיזיקלית של כל אחד מהערכים (1)-(3), וקבע לאילו מהערכים יש גדלים מספריים זהים לכל שלושת הגרפים: (1) שיפוע הגרף. (2) נקודת החיתוך של הגרף עם ציר המהירות. (3) השטח הכלוא בין הגרף לציר הזמן.", OPEN, ["graph", "understanding"], [
        S(r"(1) שיפוע", r"התאוצה. לכל הכדורים $g$", r"a_A = a_B = a_C = 10\,\text{m/s}^2"),
        S(r"(2) חיתוך עם ציר המהירות", r"המהירות ההתחלתית. שונה: $+5$, $-5$, $0$", r"v_0:\ 5,\ -5,\ 0"),
        S(r"(3) השטח", r"ההעתק מהזריקה עד הקרקע. לכולם $H = 100\,\text{m}$", r"\Delta y = H"),
    ], r"השיפוע (התאוצה) והשטח (ההעתק $H$) זהים לשלושתם. החיתוך (המהירות ההתחלתית) שונה", key=r"(1),(3) זהים"),
    P("ה", r"בסעיף זה הנח שבין כל כדור לאוויר פועל כוח חיכוך שגודלו קבוע וקטן מהמשקל של הכדור. להזכירך, כל הכדורים זהים. קבע אם גודל המהירות של כדור $A$ ברגע פגיעתו בקרקע קטן מגודל המהירות של כדור $B$ ברגע פגיעתו בקרקע, גדול ממנו או שווה לו. נמק את קביעתך.", choice(["קטן", "גדול", "שווה"], 1), ["principle", "understanding"], [
        S(r"אותה אנרגיה בהתחלה", r"אותה מסה, אותו גובה, ואותו גודל מהירות", r"E_{0,A} = E_{0,B}"),
        S(r"עבודת החיכוך", r"$B$ עולה ואז יורד, ולכן עובר דרך ארוכה יותר, והחיכוך מאבד ממנו יותר אנרגיה", r"W_f = -f \cdot s,\quad s_B > s_A"),
    ], r"גדול: כדור $B$ עובר דרך ארוכה יותר, ומאבד יותר אנרגיה לחיכוך", key=r"מהירות A גדולה ממהירות B"),
  ],
  concepts=["זריקה אנכית", "בחירת כיוון חיובי", "שיפוע, חיתוך ושטח בגרף מהירות", "חיכוך עם האוויר", "אנרגיה"],
  summary=r"שלושה כדורים מאותו מגדל: למעלה, למטה ובלי מהירות. מה זהה ומה שונה בגרפים, ומה משנה חיכוך באוויר.")
